rm -f tests/save-manager.test.ts; cat > tests/save-manager.test.mjs <<'EOF'
import assert from 'node:assert/strict';
import test from 'node:test';
import { DEFAULT_SAVE_KEY, SaveManager, migrateSave } from '../.test-build/core/SaveManager.js';
import { createDefaultProfile } from '../.test-build/player/profile.js';
import { MAX_PLAYER_LEVEL, MAX_PLAYER_XP, levelForXp, xpForLevel } from '../.test-build/player/progression.js';
class MemoryStorage { constructor(){this.data=new Map()} getItem(k){return this.data.get(k)??null} setItem(k,v){this.data.set(k,v)} removeItem(k){this.data.delete(k)} }
test('XP curve covers levels 1 through 50',()=>{assert.equal(levelForXp(0),1);assert.equal(levelForXp(MAX_PLAYER_XP),MAX_PLAYER_LEVEL);assert.ok(xpForLevel(50)>xpForLevel(49))});
test('SaveManager round trips and derives level from XP',()=>{const storage=new MemoryStorage();const manager=new SaveManager(storage);const p=createDefaultProfile(new Date('2026-01-01T00:00:00Z'),'player-1');p.displayName='Golfer';p.progression.xp=xpForLevel(8);assert.equal(manager.save(p),true);const loaded=manager.load();assert.equal(loaded.displayName,'Golfer');assert.equal(loaded.progression.level,8)});
test('corrupt JSON safely falls back',()=>{const storage=new MemoryStorage();storage.setItem(DEFAULT_SAVE_KEY,'{broken');const p=new SaveManager(storage).load();assert.equal(p.progression.level,1);assert.equal(p.displayName,'Player')});
test('v1 migration accepts flat XP and old hold control scheme',()=>{const p=migrateSave({version:1,id:'legacy',displayName:'Old',xp:xpForLevel(5),settings:{controlScheme:'hold'}});assert.equal(p.progression.level,5);assert.equal(p.settings.controlScheme,'charge')});
test('future version safely falls back',()=>{const fallback=createDefaultProfile(new Date('2026-01-01T00:00:00Z'),'fallback');const p=migrateSave({version:999,profile:{progression:{xp:MAX_PLAYER_XP}}},fallback);assert.equal(p.id,'fallback');assert.equal(p.progression.level,1)});
test('storage write failure is safe',()=>{const bad={getItem:()=>null,setItem:()=>{throw new Error('quota')},removeItem:()=>{}};assert.equal(new SaveManager(bad).save(createDefaultProfile()),false)});
EOF
rm -rf .test-build; ./node_modules/.bin/tsc src/core/SaveManager.ts src/player/types.ts src/player/progression.ts src/player/profile.ts --outDir .test-build --module NodeNext --moduleResolution NodeNext --target ES2022 --skipLibCheck || exit 1
node --test tests/save-manager.test.mjs; rc=$?; rm -rf .test-build; printf '%s\n' '=== STATUS ==='; git status --short; exit $rc
